// Generated by `just generate` from `src/plugins/claudetto/slices/reply/adapters/mod.ts`. Edit the source and run `just generate`.
// The mod handler of the `reply` slice: the `Reply` button under a message of Claude.
// The `onPress` closure runs in the environment of the plugin, so it calls `$.prompt.fill` itself.
// The mode `insert` keeps the text that the user typed already, and puts the quote at the cursor.

import type { MatchedHook } from "claude-code";
import { QUOTE_MAX_LINES } from "../limits.ts";

/** The first `QUOTE_MAX_LINES` lines of `text` as a `>` quote, with a blank line after it for the answer. */
export const quoteOf = (text: string): string =>
  `${text
    .trim()
    .split("\n")
    .slice(0, QUOTE_MAX_LINES)
    .map((line) => `> ${line}`.trimEnd())
    .join("\n")}\n\n`;

/** The address of the button. */
const REPLY = "reply";

export const onRender: MatchedHook<
  "ui.render",
  { component: "AssistantMessage" }
> = async ($, e, next) => {
  const drawn = await next(e);
  if (e.props.text.trim() === "") return drawn;
  const { Box, Button } = $.ui.resolve(e);
  return Box({
    flexDirection: "column",
    children: [
      drawn,
      Button({
        key: REPLY,
        label: "Reply",
        dimColor: true,
        onPress: () => {
          void $.prompt.fill({ text: quoteOf(e.props.text), mode: "insert" });
        },
      }),
    ],
  });
};
